<?php
$rows=db()->query("SELECT ri.*,q.question_text,q.correct_option,q.explanation FROM revision_items ri JOIN questions q ON q.id=ri.question_id ORDER BY ri.next_review_at ASC")->fetchAll();
?><div class="page-heading"><div><p class="eyebrow">RECALL & RETENTION</p><h1>Revision Centre</h1><p class="muted">Questions you answered incorrectly are collected here for review.</p></div></div><section class="card"><?php if(!$rows):?><div class="empty-state"><div>✦</div><b>Your revision list is clear</b><p>Incorrect answers from MCQ attempts will appear here automatically.</p></div><?php else:foreach($rows as $r):?><div class="revision-item"><b><?=e($r['question_text'])?></b><p class="muted">Correct option: <?=e($r['correct_option'])?></p><?php if($r['explanation']):?><p><?=e($r['explanation'])?></p><?php endif;?><small class="muted">Review due: <?=e($r['next_review_at'])?></small></div><?php endforeach;endif;?></section>
